INSERT INTO `educations` VALUES (3,2,'BS Information Technology','2016 - 2018',1,'Virtual University of Pakistan','<p>The <strong>BS Information Technology (BSIT)</strong> program is a <strong>16-year education degree</strong> designed to provide students with a <strong>comprehensive foundation</strong> in <strong>computer science, software development, networking, database management, and cybersecurity</strong>. It emphasizes a <strong>balanced approach</strong> to <strong>theoretical knowledge and practical skills</strong>, preparing graduates for diverse careers in <strong>IT management, software engineering, web development, and system administration</strong>.&nbsp;</p><p><strong>Core subjects</strong> include:&nbsp;</p><ul><li>Programming</li><li>Data Structures</li><li>Database Systems</li><li>Web Development</li><li>Cloud Computing</li><li>Cybersecurity</li><li>IT Project Management</li></ul><p><br></p>',1,'2025-02-24 01:59:12','2025-02-24 02:02:14'),(4,2,'B.Sc Computer Science','2014-2016',2,'Virtual University of Pakistan','<p>A <strong>Bachelor of Science (B.Sc.) in Computer Science</strong> is a 14 years degree that provides students with a strong foundation in computing, programming, and problem-solving. The curriculum typically includes subjects such as data structures, algorithms, database management, operating systems, artificial intelligence, cybersecurity, and software development. Students also gain practical experience through coding projects, internships, and research opportunities. The degree equips graduates with the skills needed for careers in software engineering, web development, data science, IT consulting, and more. With the growing demand for technology professionals, a B.Sc. in Computer Science opens doors to diverse job opportunities in industries such as finance, healthcare, education, and entertainment. Many graduates also choose to pursue higher studies, such as an M.Sc. or certifications, to specialize further in their field.&nbsp;</p>',1,'2025-02-24 02:03:04','2025-02-24 02:03:04');
/*!40000 ALTER TABLE `educations` ENABLE KEYS */;
UNLOCK TABLES;

