INSERT INTO `experiences` VALUES (3,2,'BARQAAB Consulting Services','IT Coordinator','2014 - todate',1,'<p>Responsible for managing and maintaining an organization\'s IT systems, ensuring smooth and efficient operations. Oversee network security, troubleshoot technical issues, and provide support to employees regarding hardware, software, and network-related concerns. Additionally, coordinate with vendors for system upgrades, software installations, and procurement of IT equipment. I also play a key role in implementing cybersecurity measures, managing data backups, and ensuring compliance with IT policies. Assist in training staff on new technologies and best practices, helping to improve overall productivity. Effective communication, problem-solving skills, and a proactive approach are essential for successfully handling the dynamic challenges of this role.</p>',1,'2025-02-24 02:07:03','2025-02-24 02:07:03'),(4,2,'Pakistan Telecommunication Company Limited','HR & Admin Executive','1995 - 2014',2,'<p>An HR and Admin Executive is responsible for managing human resources and administrative functions to ensure the smooth operation of an organization. Their duties include recruiting, onboarding, and training employees, as well as maintaining employee records and handling payroll and benefits administration. They oversee workplace policies, ensure compliance with labor laws, and address employee concerns to foster a positive work environment. Additionally, they manage office administration tasks such as coordinating meetings, handling correspondence, maintaining office supplies, and ensuring a well-organized workplace. They also play a key role in developing and implementing HR policies, performance management, and employee engagement initiatives. Strong organizational, communication, and problem-solving skills are essential for success in this role.</p>',1,'2025-02-24 02:08:20','2025-02-24 02:09:43');
