/*!40000 ALTER TABLE `project_details` DISABLE KEYS */;
INSERT INTO `project_details` VALUES (1,2,'BARQAAB Consult Services','2019-02-01',NULL,'Asset Management System (AMS)','<p>The Asset Management System is a comprehensive web-based application designed to efficiently track, manage, and optimize equipment and inventory critical to the company\'s operations. It enables seamless asset identification through QR code generation and scanning, allowing quick and accurate tracking. Users can assign assets to employees, departments, or locations, ensuring clear accountability. Additionally, the system provides monitoring of asset availability, status, and location, enhancing visibility and control. By streamlining asset management processes, it improves operational efficiency, reduces losses, and maximizes resource utilization.&nbsp;</p>','2025-02-25 23:49:55','2025-02-25 23:49:55'),(2,3,'BARQAAB Consulting Services ','2019-06-06',NULL,'Project Management System (PMS)','<p>The Project Management System (PMS) is designed to proactively identify and mitigate risks and challenges that may impact project completion. It provides real-time monitoring of task progress, project timelines, and resource utilization. The system enables tracking of budget and expense status, and actual work completed against the total allocated budget. Additionally, it helps identify bottlenecks that may cause project delays, ensuring better decision-making and improved project efficiency&nbsp;</p>','2025-02-25 23:50:46','2025-02-25 23:50:46'),(3,4,'BARQAAB Consulting Services ','2020-11-01',NULL,'Android Based Management Information System (MIS)','<p>A Management Information System (MIS) is a structured system that collects, processes, and analyzes a company\'s data to support agile, informed, and strategic decision-making. It enhances business efficiency by leveraging technology to solve problems and optimize operations.&nbsp;</p>','2025-02-25 23:52:47','2025-04-03 11:10:12'),(4,5,'BARQAAB Consulting Services','2021-05-02',NULL,'Leave Management System (LMS)','<p>A Leave Management System (LMS) is a web-based solution that automates the process of managing employee leave requests, approvals, and tracking. It ensures a seamless workflow, reduces administrative workload, and enhances transparency in leave policies.&nbsp; The system allows employees to submit leave requests online, specifying the type of leave, duration, and reason. Managers receive automated notifications for approval or rejection, ensuring a smooth and transparent process.&nbsp;</p>','2025-02-25 23:53:55','2025-04-03 11:07:09'),(5,1,'BARQAAB Consulting Services ','2018-02-02',NULL,'Human Resource Management System (HRMS)','<p>HRMS is a comprehensive web application that manages complete employee information, including personal details, transfer and posting records, promotions, educational background, work experience, and personal files. Additionally, it features automated email alerts to notify the HR manager about important updates such as CNIC expiry, contract expiry, and HR-related management reports&nbsp;</p>','2025-02-26 00:35:42','2025-02-26 00:35:42'),(6,6,'BARQAAB Consulting Services ','2021-01-01',NULL,'Web Based MIS','<p>&nbsp;A Management Information System (MIS) is a structured system that collects, processes, and analyzes a company\'s data to support agile, informed, and strategic decision-making. It enhances business efficiency by leveraging technology to solve problems and optimize operations.&nbsp;</p>','2025-04-03 11:14:27','2025-04-03 11:14:27');
/*!40000 ALTER TABLE `project_details` ENABLE KEYS */;
UNLOCK TABLES;

