INSERT INTO `projects` VALUES (1,2,1,'Human Resource Management System',1,'<p>HRMS is a comprehensive web application which includes Employee Complete Information like, Employee Personal Detail, Transfer &amp;Posting Detail, Promotion Detail, Educational Detail, Experience Detail and Employee Personal File.&nbsp; Important alters automatic email to HR manager for information like CNIC Expiry, Contract Expiry and Management related HR Reporting&nbsp;</p>',1,'2025-02-25 23:13:14','2025-02-25 23:13:14'),(2,2,2,'Asset Management System ',2,'<p>&nbsp;Asset Management System is a web application, which main purpose is to keep track of the equipment and inventory vital to the day-to-day operation of the company.&nbsp;</p>',1,'2025-02-25 23:13:56','2025-02-25 23:13:56'),(3,2,1,'Project Management System ',3,'<p>&nbsp;The purpose of Project Management System (PMS) is to foresee the risks and challenges that could derail the completion of a project. It applies proven methodologies and tools to plan, control, and monitor people, processes, and other components needed to make project a success.&nbsp;</p>',1,'2025-02-25 23:14:22','2025-02-25 23:14:22'),(4,2,2,'Management Information System ',4,'<p>&nbsp;A Management Information System (MIS) is a structured system that collects, processes, and analyzes a company\'s data to support agile, informed, and strategic decision-making. It enhances business efficiency by leveraging technology to solve problems and optimize operations.&nbsp;</p>',1,'2025-02-25 23:15:33','2025-02-25 23:15:33'),(5,2,1,'Leave Management System ',5,'<p>A Leave Management System (LMS) is a web-based solution that automates the process of managing employee leave requests, approvals, and tracking. It ensures a seamless workflow, reduces administrative workload, and enhances transparency in leave policies.&nbsp; The system allows employees to submit leave requests online, specifying the type of leave, duration, and reason. Managers receive automated notifications for approval or rejection, ensuring a smooth and transparent process.&nbsp;</p>',1,'2025-02-25 23:15:57','2025-02-25 23:15:57'),(6,2,1,'Web Based Management Information System (MIS)',6,'<p>&nbsp;A Management Information System (MIS) is a structured system that collects, processes, and analyzes a company\'s data to support agile, informed, and strategic decision-making. It enhances business efficiency by leveraging technology to solve problems and optimize operations.&nbsp;</p>',1,'2025-04-03 11:11:55','2025-04-03 11:11:55');
